ALTER TYPE "Role" ADD VALUE IF NOT EXISTS 'CAREGIVER';
ALTER TABLE "ClinicalAlert" ADD COLUMN "escalationLevel" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "lastEscalatedAt" TIMESTAMP(3);
CREATE TABLE "HaHCarePlanRevision" ("id" TEXT PRIMARY KEY,"episodeId" TEXT NOT NULL,"version" INTEGER NOT NULL,"snapshot" JSONB NOT NULL,"changedById" TEXT NOT NULL,"changedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "HaHCarePlanRevision_episodeId_fkey" FOREIGN KEY ("episodeId") REFERENCES "HaHEpisode"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "HaHCarePlanRevision_episodeId_version_key" ON "HaHCarePlanRevision"("episodeId","version");
CREATE TABLE "ClinicalAlertEvent" ("id" TEXT PRIMARY KEY,"alertId" TEXT NOT NULL,"type" TEXT NOT NULL,"actorId" TEXT,"detail" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ClinicalAlertEvent_alertId_fkey" FOREIGN KEY ("alertId") REFERENCES "ClinicalAlert"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "ClinicalAlertEvent_alertId_createdAt_idx" ON "ClinicalAlertEvent"("alertId","createdAt");
CREATE TABLE "HaHCaregiverAccess" ("id" TEXT PRIMARY KEY,"patientId" TEXT NOT NULL,"caregiverId" TEXT NOT NULL,"scope" JSONB NOT NULL,"consentBy" TEXT NOT NULL,"consentAt" TIMESTAMP(3) NOT NULL,"expiresAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),"revokedById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "HaHCaregiverAccess_patientId_fkey" FOREIGN KEY ("patientId") REFERENCES "HaHPatient"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "HaHCaregiverAccess_caregiverId_fkey" FOREIGN KEY ("caregiverId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "HaHCaregiverAccess_patientId_caregiverId_key" ON "HaHCaregiverAccess"("patientId","caregiverId");
CREATE INDEX "HaHCaregiverAccess_caregiverId_revokedAt_idx" ON "HaHCaregiverAccess"("caregiverId","revokedAt");
CREATE TABLE "HaHClinicalMessage" ("id" TEXT PRIMARY KEY,"episodeId" TEXT NOT NULL,"senderId" TEXT NOT NULL,"body" TEXT NOT NULL,"category" TEXT NOT NULL DEFAULT 'GENERAL',"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "HaHClinicalMessage_episodeId_fkey" FOREIGN KEY ("episodeId") REFERENCES "HaHEpisode"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "HaHClinicalMessage_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "HaHClinicalMessage_episodeId_createdAt_idx" ON "HaHClinicalMessage"("episodeId","createdAt");
CREATE TABLE "HaHClinicalProtocol" ("id" TEXT PRIMARY KEY,"version" INTEGER NOT NULL,"name" TEXT NOT NULL,"thresholds" JSONB NOT NULL,"responseSla" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"approvedById" TEXT,"approvalNote" TEXT,"approvedAt" TIMESTAMP(3),"activeFrom" TIMESTAMP(3),"retiredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "HaHClinicalProtocol_version_key" ON "HaHClinicalProtocol"("version");
CREATE INDEX "HaHClinicalProtocol_status_activeFrom_idx" ON "HaHClinicalProtocol"("status","activeFrom");
